CATEGORIES = [
    {"id": "fundamentals", "title": "Log & Cluster Fundamentals", "color": "sky", "blurb": "Topics, partitions, brokers, replication and ordering."},
    {"id": "producers", "title": "Producers & Delivery", "color": "mint", "blurb": "Keys, acknowledgements, idempotence, retries and transactions."},
    {"id": "consumers", "title": "Consumers & Groups", "color": "lilac", "blurb": "Offsets, rebalances, lag, processing and recovery."},
    {"id": "operations", "title": "Operations & Ecosystem", "color": "peach", "blurb": "Retention, schemas, security, Kafka Connect and monitoring."},
]

TOPICS = build_lessons([
    ("kafka-log-model", "Kafka's Distributed Log Model", "fundamentals", "basic", "Kafka stores records in append-only partition logs. Producers append records; consumers track their own offsets and can replay retained history. Brokers distribute partitions across a cluster.", "Topic orders: partition 0 [offset 0,1,2] · partition 1 [offset 0,1]", "Kafka is a durable log, not a queue that deletes a message as soon as one consumer reads it.", "Can two consumer groups independently read the same Kafka records?", "Yes. Each group tracks its own offsets, so groups can consume the same retained data independently.", ["kafka-partitions", "kafka-offsets"]),
    ("kafka-topics", "Topics, Partitions & Replicas", "fundamentals", "basic", "A topic is split into partitions that provide parallelism and ordering boundaries. Replicas copy a partition log to other brokers for availability; one replica is the leader for client traffic.", "kafka-topics.sh --describe --topic orders --bootstrap-server broker:9092", "Partition count affects throughput, consumer parallelism, file handles and operational load; choose it with growth and key distribution in mind.", "What is the unit of ordering and replication in Kafka?", "A partition is an ordered log and the replication unit. A topic's partitions do not have one global order.", ["kafka-partitions", "kafka-replication"]),
    ("kafka-partitions", "Partition Keys & Ordering", "fundamentals", "intermediate", "A key is hashed to a partition, keeping records with the same key ordered in that partition. Keys should match the entity whose order matters and should distribute load across partitions.", "key = customer_id  # preserve per-customer event order", "A hot key can overload one partition even when the topic has many partitions.", "Can Kafka guarantee total ordering across all topic partitions?", "No. Ordering is guaranteed only within a partition. If one entity needs order, use a stable key that routes its events to one partition.", ["kafka-producers", "kafka-partitions"]),
    ("kafka-replication", "Replication, Leaders & ISR", "fundamentals", "intermediate", "Kafka replicates partition logs to followers. The in-sync replica set (ISR) tracks replicas sufficiently caught up with the leader. Min ISR and producer acknowledgements determine whether writes can be accepted during failures.", "replication.factor=3 · min.insync.replicas=2 · acks=all", "Replication factor alone is not an acknowledgement guarantee; align acks, min ISR and retry policy.", "What does acks=all mean when min.insync.replicas is 2?", "The leader waits for all currently in-sync replicas to acknowledge, and the write is rejected if the ISR falls below the configured minimum.", ["kafka-producers", "kafka-availability"]),
    ("kafka-producers", "Producer Acknowledgements & Durability", "producers", "intermediate", "Producer acks controls how many broker acknowledgements a send waits for: 0, 1 or all in-sync replicas. Idempotence prevents duplicate log entries caused by producer retries within its supported session.", "acks=all · enable.idempotence=true · delivery.timeout.ms=120000", "Durability is a joint configuration across producer acks, broker replication, ISR and storage; document the trade-off.", "Does acks=all mean a record can never be lost?", "No. It is strongest when paired with replication and min ISR, but correlated failures, unsafe broker settings or application-level processing gaps can still lose business effects.", ["kafka-replication", "kafka-delivery"]),
    ("kafka-retries", "Retries, Timeouts & Backpressure", "producers", "intermediate", "Transient broker errors should be retried within a delivery deadline. Excessive retries without backpressure can increase queueing and duplicate application effects; bound in-flight work and expose failures.", "retries=10 · delivery.timeout.ms=120000 · linger.ms=5", "Retry only within a defined end-to-end budget and make downstream processing safe for duplicates.", "Why can aggressive retries make an outage worse?", "Retries multiply load on a struggling cluster and can exhaust client queues. Use bounded retry budgets, backoff, backpressure and alerting.", ["kafka-producers", "kafka-delivery"]),
    ("kafka-consumer-groups", "Consumer Groups & Parallelism", "consumers", "basic", "Consumers in the same group divide partitions among themselves. A partition is assigned to at most one group member at a time; adding consumers beyond partition count leaves some idle.", "kafka-consumer-groups.sh --describe --group billing --bootstrap-server broker:9092", "Group membership changes trigger reassignment; processing should tolerate pauses and duplicate delivery during recovery.", "A group has 12 consumers but the topic has 8 partitions. How many can actively consume?", "At most 8 consumers can own partitions at once; at least 4 will be idle unless the subscription includes other partitions.", ["kafka-offsets", "kafka-rebalances"]),
    ("kafka-offsets", "Offsets & Commit Strategies", "consumers", "intermediate", "Offsets record a consumer group's position in each partition. Auto-commit can advance past work before processing finishes; manual commits after durable processing improve recovery but may repeat work after a crash.", "Process record → commit offset only after database transaction succeeds", "Commit timing defines the replay/loss boundary; make handlers idempotent or coordinate offset and output atomically.", "What can happen if an offset is committed before processing completes?", "A crash after commit but before the side effect completes causes the restarted consumer to skip the record, losing that processing effect.", ["kafka-delivery", "kafka-consumer-groups"]),
    ("kafka-rebalances", "Rebalances, Assignment & Static Membership", "consumers", "intermediate", "A rebalance redistributes partitions when group membership or subscriptions change. Long processing pauses, frequent restarts and slow poll loops can trigger churn; cooperative assignment and static membership can reduce disruption.", "Tune max.poll.interval.ms to exceed bounded processing time; keep poll progress healthy", "Do not increase timeouts to hide unbounded processing; separate slow work and preserve cancellation and backpressure.", "Why does a consumer repeatedly leave and rejoin its group?", "It may exceed max.poll.interval.ms, fail heartbeats, restart, or encounter coordinator/network issues. Correlate group logs, processing duration and rebalance metrics.", ["kafka-consumer-groups", "kafka-offsets"]),
    ("kafka-delivery", "At-Most-Once, At-Least-Once & Exactly-Once", "consumers", "advanced", "At-most-once risks loss; at-least-once can repeat processing; exactly-once semantics apply within defined Kafka transactions and do not make arbitrary external side effects exactly once. Idempotency is essential at system boundaries.", "Write output and offset in one Kafka transaction; use an idempotency key for external DB writes", "State precisely which boundary has a guarantee: Kafka-to-Kafka transactions do not automatically include a relational database.", "Does Kafka's exactly-once mode make an email send exactly once?", "No. The email provider is outside Kafka's transaction. Use an idempotent operation, deduplication key or an outbox workflow for the external side effect.", ["kafka-offsets", "kafka-transactions"]),
    ("kafka-transactions", "Idempotent Producers & Transactions", "producers", "advanced", "Idempotent producers attach sequence numbers so broker retries do not duplicate records. Transactions atomically write to multiple partitions and can include consumed offsets for Kafka-to-Kafka processing.", "transactional.id=invoice-enricher-1 · isolation.level=read_committed", "Transactional IDs must be stable per logical producer instance and unique among concurrent instances.", "What does read_committed change for a consumer?", "It hides aborted transactional records and exposes only committed transactions, at the cost of waiting behind the last stable offset.", ["kafka-delivery", "kafka-offsets"]),
    ("kafka-retention", "Retention, Compaction & Tombstones", "operations", "intermediate", "Time/size retention deletes old segments; log compaction keeps the latest value per key over time. A tombstone is a keyed null value that marks deletion and is retained for a configured period before cleanup.", "cleanup.policy=compact · delete.retention.ms=86400000", "Compaction is asynchronous and not a substitute for an immediate point-in-time delete from every replica or backup.", "When would you use compaction instead of time retention?", "For changelog-like topics where consumers need the latest value per key, such as rebuilding a state store, rather than a complete event history forever.", ["kafka-log-model", "kafka-schemas"]),
    ("kafka-schemas", "Schema Evolution & Compatibility", "operations", "intermediate", "Schemas describe record structure and compatibility rules. Backward, forward and full compatibility determine whether old and new producers and consumers can coexist during rolling deployments.", "Add an optional field with a default before making readers depend on it", "Deploy readers that tolerate the new field before producers begin emitting it; test compatibility in CI.", "Why is adding a required field risky during a rolling deploy?", "Old consumers may not understand it and old producers may omit it. Use compatible defaults and a staged reader-first rollout.", ["kafka-retention", "kafka-producers"]),
    ("kafka-security", "Authentication, ACLs & Encryption", "operations", "advanced", "Kafka security combines TLS for transport, authentication such as SASL or mTLS, and authorization through ACLs or an external policy engine. Scope principals to required topics, groups and transactional IDs.", "Grant read on topic orders and group billing-v2; deny broad cluster access", "Authentication identifies a principal; authorization decides its allowed Kafka operations.", "A client authenticates successfully but gets TopicAuthorizationException. Why?", "The principal is recognized but lacks an ACL or policy grant for the topic/group/action, or the resource pattern does not match.", ["kafka-consumer-groups", "kafka-producers"]),
    ("kafka-lag", "Consumer Lag & Capacity Planning", "operations", "intermediate", "Consumer lag is the distance between the log end and a group's committed position. It rises when arrival rate exceeds processing throughput or when partitions are unassigned; it is a signal to investigate, not a root cause.", "Compare records-lag, bytes-in, processing latency and partition assignment", "Adding consumers helps only when there are unassigned partitions and the bottleneck is per-consumer capacity.", "Lag rises while all partitions are assigned. What do you inspect?", "Measure processing time, downstream latency, batch size, poll behavior, hot partitions and errors. Scale consumers only if there is parallelism available.", ["kafka-consumer-groups", "kafka-rebalances"]),
    ("kafka-connect", "Kafka Connect & Connector Delivery", "operations", "intermediate", "Kafka Connect runs source connectors that ingest into Kafka and sink connectors that export records. Worker mode, task count, offset/config/status topics and connector error handling determine deployment and recovery behavior.", "Source connector → topic → consumer group or sink connector", "Connector task parallelism is limited by source partitions or sink behavior; more tasks do not always mean more throughput.", "A sink connector is stuck retrying one malformed record. What would you inspect?", "Check connector error tolerance, dead-letter queue configuration, converter/schema errors and sink task logs. Preserve the original record and its context for replay.", ["kafka-delivery", "kafka-security"]),
    ("kafka-streams", "Kafka Streams & Stateful Processing", "operations", "advanced", "Kafka Streams builds stateful processing apps with local state stores backed by changelog topics. Repartitioning can change key distribution; joins need compatible keys and windows define event-time retention.", "groupByKey → windowedBy → aggregate → to output topic", "Stateful apps need enough local storage, changelog recovery capacity and deliberate event-time/late-arrival policy.", "Why does a Kafka Streams join sometimes repartition records?", "The input topics may not be partitioned by the join key. Repartitioning groups matching keys into the same task before the join.", ["kafka-partitions", "kafka-retention"]),
    ("kafka-cluster-sizing", "Partition Count, Broker Sizing & Availability", "operations", "advanced", "Partition count sets concurrency and operational overhead. Broker storage, network, page cache, replication traffic and recovery time all matter; size for throughput and failure recovery, not only average traffic.", "Estimate bytes/day × retention × replication factor, then add recovery and growth headroom", "A large partition count can slow leader elections, reassignments and file management; validate with workload measurements.", "Why can adding partitions to a topic be a compatibility issue?", "Key-to-partition mapping may change as the partition count changes, which can break per-key ordering across the old and new mapping.", ["kafka-partitions", "kafka-replication"]),
], "KAFKA", "Kafka is a durable event log split into ordered partitions, with independent consumers tracking their own progress.")

